        n = len(data)
        while i < n-1:
            # Find 0xFF
            if data[i] != 0xFF:
                i += 1
                continue
            # skip padding
            while i < n and data[i] == 0xFF:
                i += 1
            if i >= n:
                break
            marker = data[i]
            i += 1
            if marker == 0xD9 or marker == 0xD8:
                continue
            if 0xD0 <= marker <= 0xD7 or marker == 0x01:
                continue
            if i+1 >= n:
                break
            length = (data[i]<<8) + data[i+1]
            if length < 2:
                break
            if marker in (0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF):
                if i+7 >= n:
                    break
                h = (data[i+3]<<8)+data[i+4]
                w = (data[i+5]<<8)+data[i+6]
                if w>0 and h>0:
                    return (w,h)
                break
            i += length
        return None
    except:
        return None

def img_dim_gif(data):
    try:
        if len(data) < 10 or data[:6] not in (b'GIF87a', b'GIF89a'):
            return None
        w = struct.unpack('<H', data[6:8])[0]
        h = struct.unpack('<H', data[8:10])[0]
        return (w,h)
    except:
        return None

def img_dim_qoi(data):
    try:
        if len(data) < 14 or data[:4] != b'qoif':
            return None
        w = struct.unpack('>I', data[4:8])[0]
        h = struct.unpack('>I', data[8:12])[0]
        return (w,h)
    except:
        return None

def img_dim_webp(data):
    try:
        if len(data) < 12 or data[:4] != b'RIFF' or data[8:12] != b'WEBP':
            return None
        if len(data) < 16:
            return None
        chunk = data[12:16]
        if chunk == b'VP8 ':
            if len(data) < 30:
                return None
            w = struct.unpack('<H', data[26:28])[0] & 0x3FFF
            h = struct.unpack('<H', data[28:30])[0] & 0x3FFF
            return (w,h)
        elif chunk == b'VP8L':
            if len(data) < 25:
                return None
            b1,b2,b3,b4 = data[21], data[22], data[23], data[24]
            w = ((b2 & 0x3F)<<8 | b1) + 1
            h = ((b4 & 0xF)<<10 | (b3<<2) | ((b2 & 0xC0)>>6)) + 1
            return (w,h)
        elif chunk == b'VP8X':
            if len(data) < 30:
                return None
            w = int.from_bytes(data[24:27],'little')+1
            h = int.from_bytes(data[27:30],'little')+1
            return (w,h)
        return None
    except:
        return None

def img_dim_tiff(data):
    try:
        if len(data) < 8:
            return None
        endian = data[:2]
        if endian == b'II':
            bo = '<'
        elif endian == b'MM':
            bo = '>'
        else:
            return None
        magic = struct.unpack(bo+'H', data[2:4])[0]
        if magic != 42:
            return None
        off = struct.unpack(bo+'I', data[4:8])[0]
        if off+2 > len(data):
            return None
        n = struct.unpack(bo+'H', data[off:off+2])[0]
        w=h=None
        for idx in range(n):
            eoff = off+2+idx*12
            if eoff+12 > len(data):
                break
            tag = struct.unpack(bo+'H', data[eoff:eoff+2])[0]
            typ = struct.unpack(bo+'H', data[eoff+2:eoff+4])[0]
            cnt = struct.unpack(bo+'I', data[eoff+4:eoff+8])[0]
            val = data[eoff+8:eoff+12]
            # For SHORT (3) with cnt==1, value in first 2 bytes; for LONG (4), 4 bytes
            if tag == 256:
                if typ == 3:
                    w = struct.unpack(bo+'H', val[0:2])[0]
                elif typ == 4:
                    w = struct.unpack(bo+'I', val[0:4])[0]
                else:
                    # Try to follow offset? For simplicity, if cnt==1 and typ==3/4 handled, else ignore
                    pass
            elif tag == 257:
                if typ == 3:
                    h = struct.unpack(bo+'H', val[0:2])[0]
                elif typ == 4:
                    h = struct.unpack(bo+'I', val[0:4])[0]
        if w and h:
            return (w,h)
        return None
    except:
        return None

def img_dim_xwd(data):
    try:
        if len(data) < 100:
            return None
        vals = struct.unpack('>7I', data[:28])
        header_size, version = vals[0], vals[1]
        if version != 7:
            return None
        if header_size < 100 or header_size > 1000:
            return None
        w, h = vals[4], vals[5]
        if w <= 0 or h <= 0 or w > 10000 or h > 10000:
            return None
        return (w,h)
    except:
        return None

def img_dim_svg(data):
    try:
        # data may be bytes, decode as utf-8 ignore
        try:
            txt = data.decode('utf-8', errors='ignore')
        except:
            return None
        if '<svg' not in txt.lower():
            return None
        import re as _re
        # Try width/height attributes
        m_w = _re.search(r'width\s*=\s*["\']?\s*([\d.]+)', txt, _re.I)
        m_h = _re.search(r'height\s*=\s*["\']?\s*([\d.]+)', txt, _re.I)
        w=h=None
        if m_w:
            try:
                w = int(float(m_w.group(1)))
            except:
                pass
        if m_h:
            try:
                h = int(float(m_h.group(1)))
            except:
                pass
        if w and h and w>0 and h>0 and w<10000 and h<10000:
            return (w,h)
        # Try viewBox
        m_vb = _re.search(r'viewBox\s*=\s*["\']\s*[\d.\-]+\s+[\d.\-]+\s+([\d.]+)\s+([\d.]+)\s*["\']', txt, _re.I)
        if m_vb:
            try:
                w = int(float(m_vb.group(1))); h=int(float(m_vb.group(2)))
                if w>0 and h>0:
                    return (w,h)
            except:
                pass
        # Default
        return (100,100)
    except:
        return None

def detect_format(data):
    # returns format string or None
    if len(data) >= 8 and data[:8] == b'\x89PNG\r\n\x1a\n':
        return "png"
    if len(data) >= 3 and data[:2] == b'\xff\xd8':
        return "jpeg"
    if len(data) >= 6 and data[:6] in (b'GIF87a', b'GIF89a'):
        return "gif"
    if len(data) >= 14 and data[:4] == b'qoif':
        return "qoi"
    if len(data) >= 8 and ((data[:2]==b'II' and data[2:4]==b'*\x00') or (data[:2]==b'MM' and data[2:4]==b'\x00*')):
        # More lenient: check magic 42
        try:
            if data[:2]==b'II':
                if struct.unpack('<H', data[2:4])[0]==42:
                    return "tiff"
            else:
                if struct.unpack('>H', data[2:4])[0]==42:
                    return "tiff"
        except:
            pass
    if len(data) >= 12 and data[:4]==b'RIFF' and data[8:12]==b'WEBP':
        return "webp"
    # XWD: check version 7
    if len(data) >= 28:
        try:
            vals = struct.unpack('>7I', data[:28])
            if vals[1]==7 and 100 <= vals[0] <= 2000 and 0 < vals[4] <= 10000 and 0 < vals[5] <= 10000:
                # Additional check: pixmap_format 0-2, depth reasonable
                return "xwd"
        except:
            pass
    # SVG: text containing <svg
    try:
        txt = data[:2000].decode('utf-8', errors='ignore').lower()
        if '<svg' in txt:
            return "svg"
    except:
        pass
    return None

def get_dimensions(data):
    fmt = detect_format(data)
    if fmt == "png":
        d = img_dim_png(data)
        if d: return (d[0], d[1], fmt)
    elif fmt == "jpeg":
        d = jpeg_dimensions(data)
        if d: return (d[0], d[1], fmt)
    elif fmt == "gif":
        d = img_dim_gif(data)
        if d: return (d[0], d[1], fmt)
    elif fmt == "qoi":
        d = img_dim_qoi(data)
        if d: return (d[0], d[1], fmt)
    elif fmt == "webp":
        d = img_dim_webp(data)
        if d: return (d[0], d[1], fmt)
    elif fmt == "tiff":
        d = img_dim_tiff(data)
        if d: return (d[0], d[1], fmt)
    elif fmt == "xwd":
        d = img_dim_xwd(data)
        if d: return (d[0], d[1], fmt)
    elif fmt == "svg":
        d = img_dim_svg(data)
        if d: return (d[0], d[1], fmt)
    return (None, None, None)

