def resample_pixels(pixels, sw, sh, dw, dh):
    # Simple box average resampling in Python (for small images, ok; for large, may be slow but QOI/XWD/SVG rarely large)
    # pixels is list length sw*sh of (r,g,b,a)
    try:
        if sw==dw and sh==dh:
            return pixels[:dw*dh]
        # For each dst pixel, average src region
        out=[]
        x_ratio = sw / dw
        y_ratio = sh / dh
        for dy in range(dh):
            y0 = int(dy * y_ratio)
            y1 = int((dy+1)*y_ratio)
            if y1<=y0: y1=y0+1
            if y1>sh: y1=sh
            for dx in range(dw):
                x0=int(dx*x_ratio)
                x1=int((dx+1)*x_ratio)
                if x1<=x0: x1=x0+1
                if x1>sw: x1=sw
                rsum=gsum=bsum=asum=0
                cnt=0
                for sy in range(y0,y1):
                    base=sy*sw
                    for sx in range(x0,x1):
                        r,g,b,a=pixels[base+sx]
                        rsum+=r; gsum+=g; bsum+=b; asum+=a
                        cnt+=1
                if cnt==0:
                    out.append((0,0,0,255))
                else:
                    out.append((rsum//cnt, gsum//cnt, bsum//cnt, asum//cnt))
        return out
    except:
        return None

