            elif fmt=="jpeg":
                loader = gd.gdImageCreateFromJpeg
            elif fmt=="gif":
                loader = gd.gdImageCreateFromGif
            elif fmt=="webp":
                loader = gd.gdImageCreateFromWebp
            elif fmt=="tiff":
